// The billing API lives on another host. In production this is a real service.
export const API = 'https://api.acme-billing.example';

export interface Account { name: string; plan: string; status: 'active' | 'past_due' | 'suspended'; seats: number }
export interface Invoice { id: string; customer: string; amount: number; status: 'open' | 'paid' | 'overdue'; due: string }
export interface Me { id: string; name: string; role: 'owner' | 'viewer' }

/** Server-side data access. Runs in React Server Components. */
export async function get<T>(path: string): Promise<T> {
  const res = await fetch(API + path, { cache: 'no-store' });
  if (!res.ok) throw new Error(`${path} failed with ${res.status}`);
  return res.json() as Promise<T>;
}

export const money = (n: number) => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
import { get, money, type Account, type Invoice, type Me } from '../lib/api';
import { PayButton } from './pay-button';

export const dynamic = 'force-dynamic';

const BANNER: Record<string, string | undefined> = {
  past_due: 'Your payment method failed. Update it to keep sending invoices.',
  suspended: 'This account is suspended. Invoices cannot be sent or paid.',
};

export default async function InvoicesPage() {
  const [account, invoices, me] = await Promise.all([get<Account>('/v1/account'), get<Invoice[]>('/v1/invoices'), get<Me>('/v1/me')]);
  const banner = BANNER[account.status];
  return (
    <>
      <h1 data-testid="account-name">{account.name}</h1>
      <p className="muted" data-testid="plan">
        {account.plan} plan · {account.seats} seats
      </p>
      {banner && (
        <div role="status" className={`banner banner--${account.status}`} data-testid="banner">
          {banner}
        </div>
      )}
      <h2>Invoices</h2>
      {invoices.length === 0 ? (
        <p data-testid="empty">No invoices yet. Create your first invoice to get paid.</p>
      ) : (
        <table className="table" data-testid="invoices">
          <tbody>
            {invoices.map((inv) => (
              <tr key={inv.id}>
                <td>{inv.customer}</td>
                <td>{inv.due}</td>
                <td className={`status status--${inv.status}`}>{inv.status}</td>
                <td className="num">{money(inv.amount)}</td>
                <td>{inv.status !== 'paid' && me.role === 'owner' && account.status !== 'suspended' ? <PayButton id={inv.id} /> : null}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  );
}
import { get, type Account, type Me } from '../../lib/api';

export const dynamic = 'force-dynamic';

export default async function Settings() {
  const [me, account] = await Promise.all([get<Me>('/v1/me'), get<Account>('/v1/account')]);
  return (
    <>
      <h1>Settings</h1>
      <p data-testid="settings-role">{me.role === 'owner' ? `You can change billing for ${account.name}.` : 'Only the account owner can change billing.'}</p>
    </>
  );
}
'use client';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { API } from '../lib/api';

/** A client-side write: the browser calls the API directly, then refreshes server components. */
export function PayButton({ id }: { id: string }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  return (
    <button
      className="btn"
      disabled={busy}
      onClick={async () => {
        setBusy(true);
        await fetch(`${API}/v1/invoices/${id}/pay`, { method: 'POST' });
        router.refresh();
        setBusy(false);
      }}
    >
      Mark paid
    </button>
  );
}
'use client';
import { useCallback, type ReactNode } from 'react';
import { useRouter } from 'next/navigation';
import { StagecraftRoot } from '@stagecraft/react';

export function Providers({ children }: { children: ReactNode }) {
  const router = useRouter();
  // Server components hold the data: re-fetch them when the prototype state changes.
  const refresh = useCallback(() => router.refresh(), [router]);
  return <StagecraftRoot onDataChange={refresh}>{children}</StagecraftRoot>;
}
import type { ReactNode } from 'react';
import Link from 'next/link';
import { Providers } from './providers';
import { get, type Me } from '../lib/api';
import './globals.css';

export const metadata = { title: 'Acme Billing' };

export default async function RootLayout({ children }: { children: ReactNode }) {
  const me = await get<Me>('/v1/me');
  return (
    <html lang="en">
      <body>
        <nav className="nav">
          <strong>Acme Billing</strong>
          <Link href="/">Invoices</Link>
          <Link href="/settings">Settings</Link>
          <span className="spacer" />
          <span data-testid="me">
            {me.name} · {me.role}
          </span>
        </nav>
        <main className="main">
          <Providers>{children}</Providers>
        </main>
      </body>
    </html>
  );
}
:root { --bg:#f7f7f5; --fg:#1c1c1e; --muted:#6a6a6f; --line:#e3e3e0; --brand:#0f6b5c; --warn-bg:#fff4dd; --warn:#7a4b00; --bad-bg:#fdecec; --bad:#a61b1b; --space:16px; }
* { box-sizing: border-box; }
body { margin:0; font:15px/1.5 ui-sans-serif, system-ui, sans-serif; background:var(--bg); color:var(--fg); }
.nav { display:flex; gap:var(--space); align-items:center; padding:12px 24px; background:#fff; border-bottom:1px solid var(--line); }
.nav a { color:var(--fg); text-decoration:none; }
.spacer { flex:1; }
.main { padding:24px; max-width:960px; }
.muted { color:var(--muted); }
.banner { padding:12px 16px; border-radius:10px; margin:12px 0; }
.banner--past_due { background:var(--warn-bg); color:var(--warn); }
.banner--suspended { background:var(--bad-bg); color:var(--bad); }
.table { width:100%; border-collapse:collapse; background:#fff; border:1px solid var(--line); }
.table td { padding:8px 12px; border-bottom:1px solid var(--line); }
.num { text-align:right; font-variant-numeric:tabular-nums; }
.status--overdue { color:var(--bad); } .status--paid { color:var(--brand); }
.btn { font:inherit; padding:4px 10px; border-radius:8px; border:1px solid var(--brand); background:var(--brand); color:#fff; cursor:pointer; }
# Stagecraft prototyping rules

This repo is set up for prototyping with Stagecraft. The app runs on **mock data** through the Stagecraft proxy. Designers and PMs prototype here. Your changes must be real, shippable code.

## Run it
- Start: `npx --no stagecraft dev` (starts the dev server and the proxy). Open the proxy URL, not the dev server URL.
- The `stagecraft` MCP server gives you tools: `state_catalog`, `state_set`, `persona_set`, `flags_set`, `variant_select`, `scenario_save`, `scenario_load`, `mockdb_query`, `mockdb_seed`, `mock_endpoints`, `fault_set`, `tape_create`, `tape_play`, `preview_screenshot`.
- If a tool says the proxy is not running, start it. Do not ask the user to run commands.

## Hard rules
1. **No production data or secrets.** Never add real API hosts, keys or connection strings. All API calls are served by mocks in `stagecraft/`.
2. **Mock code stays in `stagecraft/`.** Product code must never import from `stagecraft/`. Product code may import `@stagecraft/react` (it is a no-op in production).
3. **Use the design system.** Before you make a new component, look for an existing one. Use design tokens, not hard-coded colors or spacing.
4. **Every new endpoint needs a mock.** Add a handler in `stagecraft/mocks.ts` and seed data in `stagecraft/seed.ts`. Check `mock_endpoints` for requests with no mock.
5. **Every new screen needs its states.** Empty, loading, error, and each product state that changes the screen. Add states to `stagecraft/states.ts`.
6. **Check your work visually.** After a UI change, call `preview_screenshot` for each changed screen in the states that matter. Fix what you see before you say you are done.
7. **Options go in variants, not branches.** When asked for options, wrap the region in `<Variant name="..." options={{ A: ..., B: ... }} />` from `@stagecraft/react`.
8. **Do not merge, deploy or make links public.** Those need a human.

## Where things are
- `stagecraft.config.ts`: proxy config, API origins, personas, flags.
- `stagecraft/seed.ts`: initial mock DB. `stagecraft/mocks.ts`: request handlers. `stagecraft/states.ts`: state catalog.
- `stagecraft/scenarios/*.json`: saved scenarios. `stagecraft/tapes/*.json`: product-agent conversation tapes.

## Skills
Use the skills in your skills folder: `setup`, `build-screen`, `add-state`, `create-variant`, `apply-figma-frame`, `make-tape`, `self-check`, `handoff`.

