1	import { createRequire } from 'node:module';
2	import { pathToFileURL } from 'node:url';
3	
4	/** Env names that look like production secrets. Never passed to the dev server. */
5	export const SECRET_DENYLIST = /^(?:.*_)?(?:PROD|PRODUCTION)_|DATABASE_URL|_SECRET$|_SECRET_KEY$|PRIVATE_KEY|AWS_SECRET|STRIPE_SECRET/i;
6	
7	export function preloadUrl(): string {
8	  try {
9	    return import.meta.resolve('@stagecraft/server/preload');
10	  } catch {
11	    return pathToFileURL(createRequire(import.meta.url).resolve('@stagecraft/server/preload')).href;
12	  }
13	}
14	
15	/**
16	 * Environment for a dev server behind the Stagecraft proxy:
17	 * no secret-looking vars, STAGECRAFT=1, and the server-side fetch interceptor (SSR/RSC).
18	 */
19	export function devServerEnv(opts: { proxyUrl: string; apiOrigins: string[]; base?: NodeJS.ProcessEnv; extra?: Record<string, string> }): Record<string, string> {
20	  const env: Record<string, string> = {};
21	  for (const [k, v] of Object.entries(opts.base ?? process.env)) if (v !== undefined && !SECRET_DENYLIST.test(k)) env[k] = v;
22	  Object.assign(env, opts.extra ?? {});
23	  const imp = `--import ${preloadUrl()}`;
24	  env.NODE_OPTIONS = env.NODE_OPTIONS?.includes('stagecraft') ? env.NODE_OPTIONS : `${env.NODE_OPTIONS ?? ''} ${imp}`.trim();
25	  env.STAGECRAFT = '1';
26	  env.VITE_STAGECRAFT = '1';
27	  env.NEXT_PUBLIC_STAGECRAFT = '1';
28	  env.STAGECRAFT_PROXY = opts.proxyUrl;
29	  env.STAGECRAFT_API_ORIGINS = JSON.stringify(opts.apiOrigins);
30	  return env;
31	}
