2	import type { RuntimeEvent, SessionInfo, StagecraftRuntime } from './types.ts';
3	import { mountPanel } from './panel.ts';
4	
5	(function main() {
6	  const boot = window.__STAGECRAFT_BOOT__;
7	  if (!boot || window.__STAGECRAFT__) return;
8	  let info: SessionInfo = boot.session;
9	  let catalog = boot.catalog;
10	  const defaults = boot.defaults;
11	  const sid: string = info.id;
12	  const SESSION_HEADER = 'x-stagecraft-session';
13	  const listeners = new Map<RuntimeEvent, Set<(d: any) => void>>();
14	  let adapter: string | null = null;
15	  const pendingVariants = new Map<string, string[]>();
16	
17	  const emit = (e: RuntimeEvent, d?: any) => listeners.get(e)?.forEach((fn) => fn(d));
18	
19	  // ---------- network routing ----------
20	  const here = location.origin;
21	  const fullOrigins: string[] = catalog.apiOrigins.filter((o: string) => !o.startsWith('/')).map((o: string) => new URL(o).origin);
22	
23	  /** Returns the URL to use and whether to tag it with the session. */
24	  function route(input: string): { url: string; tag: boolean } {
25	    let u: URL;
26	    try {
27	      u = new URL(input, location.href);
28	    } catch {
29	      return { url: input, tag: false };
30	    }
31	    if (u.origin === here) {
32	      // Tag every same-origin request: server-rendered frameworks fetch data on the server
33	      // for page and RSC requests, and the proxy must know the session for those too.
34	      return { url: input, tag: true };
35	    }
36	    const wsToHttp = u.protocol === 'wss:' ? 'https:' : u.protocol === 'ws:' ? 'http:' : u.protocol;
37	    const origin = `${wsToHttp}//${u.host}`;
38	    if (fullOrigins.includes(origin)) {
39	      return { url: `${here}/__stagecraft/mock/${encodeURIComponent(origin)}${u.pathname}${u.search}`, tag: true };
40	    }
41	    return { url: input, tag: false };
42	  }
43	
44	  function withSid(url: string) {
45	    if (sid === 'main') return url;
46	    const u = new URL(url, location.href);
47	    u.searchParams.set('__sc_sid', sid);
48	    return u.href;
49	  }
50	
51	  const origFetch = window.fetch.bind(window);
52	  window.fetch = function (input: RequestInfo | URL, init?: RequestInit) {
53	    const raw = input instanceof Request ? input.url : String(input);
54	    const r = route(raw);
55	    if (!r.tag) return origFetch(input as RequestInfo, init);
56	    const req = new Request(input instanceof Request ? new Request(r.url, input) : r.url, init);
57	    if (sid !== 'main') req.headers.set(SESSION_HEADER, sid);
58	    return origFetch(req);
59	  };
60	
61	  const XO = XMLHttpRequest.prototype.open;
62	  const XS = XMLHttpRequest.prototype.send;
63	  XMLHttpRequest.prototype.open = function (this: XMLHttpRequest & { __sc?: boolean }, method: string, url: string | URL, ...rest: any[]) {
64	    const r = route(String(url));
65	    this.__sc = r.tag;
66	    return (XO as any).call(this, method, r.url, ...(rest.length ? rest : [true]));
67	  } as any;
68	  XMLHttpRequest.prototype.send = function (this: XMLHttpRequest & { __sc?: boolean }, body?: any) {
69	    if (this.__sc && sid !== 'main') this.setRequestHeader(SESSION_HEADER, sid);
70	    return XS.call(this, body);
71	  };
